// Helper for Tracking Map
const TrackingMap: React.FC<{ order: any }> = ({ order }) => {
    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstance = useRef<any>(null);
    const courierMarkerRef = useRef<any>(null);

    useEffect(() => {
        if (!mapRef.current || !window.L || !order.deliveryPersonId) return;

        // Init Map
        if (!mapInstance.current) {
            const initialLat = order.locationCoordinates?.lat || 5.6506;
            const initialLng = order.locationCoordinates?.lng || -0.1962;

            mapInstance.current = window.L.map(mapRef.current).setView([initialLat, initialLng], 14);
            window.L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
                attribution: '&copy; OpenStreetMap',
            }).addTo(mapInstance.current);

            // Add Destination Marker
            window.L.marker([initialLat, initialLng], {
                 icon: window.L.divIcon({ html: '<i class="fa-solid fa-house text-red-600 text-2xl drop-shadow-md"></i>', className: 'bg-transparent' })
            }).addTo(mapInstance.current);

            // Add Vendor Marker
            if(order.pickupCoordinates) {
                 window.L.marker([order.pickupCoordinates.lat, order.pickupCoordinates.lng], {
                     icon: window.L.divIcon({ html: '<i class="fa-solid fa-store text-purple-600 text-2xl drop-shadow-md"></i>', className: 'bg-transparent' })
                }).addTo(mapInstance.current);
            }
        }

        // Subscribe to Courier Location
        const channel = supabase.channel(`courier_tracking:${order.deliveryPersonId}`)
            .on('broadcast', { event: 'location' }, (payload) => {
                const { lat, lng } = payload.payload;

                if (courierMarkerRef.current) {
                    courierMarkerRef.current.setLatLng([lat, lng]);
                } else {
                    courierMarkerRef.current = window.L.marker([lat, lng], {
                        icon: window.L.divIcon({
                            className: 'bg-transparent',
                            html: '<div class="w-8 h-8 bg-blue-600 rounded-full border-2 border-white shadow-lg flex items-center justify-center text-white"><i class="fa-solid fa-motorcycle text-xs"></i></div>'
                        })
                    }).addTo(mapInstance.current);
                }
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };

    }, [order]);

    return <div ref={mapRef} className="w-full h-48 bg-gray-200 rounded-xl mb-4 z-0"></div>;
};

