                            </div>
                            <div className="p-3 flex flex-col flex-grow justify-between">
                                <h3 className="text-xs font-bold text-gray-800 line-clamp-2 mb-1">{product.title}</h3>
                                <div className="flex items-center justify-between mt-1">
                                    <span className="text-sm font-extrabold text-gray-900">{product.currency}{product.price.toFixed(2)}</span>
                                    <button 
                                        className="w-7 h-7 rounded-full bg-black text-white flex items-center justify-center shadow-md active:scale-90 hover:bg-primary transition-colors"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            addToCart(product);
                                        }}
                                        disabled={product.stock === 0}
                                    >
                                        <i className="fa-solid fa-plus text-xs"></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson> & { phoneNumber?: string }) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  // New Logistics
  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

// Coordinate Resolver Helper
const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    // Default fallback to Legon Campus center if completely unknown
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              // Enhanced Notification
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

                  // Vendor Alert
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              // Driver Alert
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as Order;
                  if (currentRoleRef.current === 'deliveryPerson' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.deliveryPersonId) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
              showToast("Connection failed. Please check your internet or API keys.", "error");
          }
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
          if (e.message !== "Vendor account pending approval" && e.message !== "Account Suspended") {
             // throw e; // don't rethrow to keep app alive
          }
      } 
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (error) throw error;

          if (data) {
              if (data.isBanned) {
                  throw new Error("Account Suspended");
              }

              if (data.roles?.includes('vendor') && !data.roles.includes('admin')) {
                  const { data: v } = await supabase.from('vendors').select('is_approved').eq('user_id', userId).maybeSingle();
                  if (v && v.is_approved === false) {
                       throw new Error("Vendor account pending approval");
                  }
              }

              const user: User = { ...data, roles: data.roles || ['buyer'] };
              setCurrentUser(user);

              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
          if (e.message === "Account Suspended" || e.message === "Vendor account pending approval") {
               await supabase.auth.signOut();
               setCurrentUser(null);
               throw e; 
          }
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e) { 
                 console.error(`Fetch ${table} failed:`, e);
                 return null;
             }
          };

          // Fetch tables individually.
          // Explicitly using 'couriers' table
          const [pData, vData, oData, dDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('couriers') 
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
                  locationCoordinates: o.locationCoordinates || o.location_coordinates,
                  pickupCoordinates: o.pickupCoordinates || o.pickup_coordinates,
              })) as Order[]);
          }

          // Manual Join for Couriers + Profiles
          // This fetches profile info for each courier
          let dData = dDataRaw;
          if (dDataRaw && dDataRaw.length > 0) {
              try {
                  const userIds = [...new Set(dDataRaw.map((d: any) => d.user_id).filter(Boolean))];
                  if (userIds.length > 0) {
                      const { data: profiles } = await supabase
                          .from('profiles')
                          .select('id, name, email')
                          .in('id', userIds);

                      if (profiles) {
                          const profileMap = new Map(profiles.map((p: any) => [p.id, p]));
                          dData = dDataRaw.map((d: any) => ({
                              ...d,
                              profiles: profileMap.get(d.user_id) || {}
                          }));
                      }
                  }
              } catch (err) {
                  console.error("Manual profile join failed for couriers", err);
              }
          }

          if (dData) setDeliveryPersons(dData.map((d: any) => {
             const profile = d.profiles || {}; 
             const name = profile.name || 'Courier';

             // LOGIC: Map 'verified' boolean to 'status' string
             // Null/Undefined/False -> 'pending' (Visibility Fix: Treat false as pending so Admins see them)
             // True -> 'approved'

             let derivedStatus: 'pending' | 'approved' | 'rejected' | 'suspended' = 'pending';
             if (d.verified === true) derivedStatus = 'approved';
             else derivedStatus = 'pending';

             // Override with explicit status column if available and valid
             if (d.status && ['approved', 'rejected', 'suspended'].includes(d.status)) {
                 derivedStatus = d.status as any;
             }

             return {
                 ...d,
                 id: d.id,
                 userId: d.user_id,
                 fullName: name, // From profiles
                 vehicleType: 'Motorbike', // Default since often missing in simple 'couriers' table

                 onlineStatus: d.online_status, 
                 currentLat: d.current_lat,
                 currentLng: d.current_lng,
                 availabilityStatus: d.availability_status,
                 verified: d.verified,

                 status: derivedStatus,
                 rating: d.delivery_rating || 5.0
             };
          }) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }

          setConnectionError(false); 
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
          }
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      // Login attempt logic simplified to avoid pre-check which may fail due to RLS
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
           return { success: false, error: error.message === "Invalid login credentials" ? "Invalid email or password" : error.message };
      }

      if (data.user) {
          try {
            const user = await fetchUserProfile(data.user.id);
            if (!user) return { success: false, error: "Account profile missing. Please contact support." };

            fetchData();

            let role: Role = 'buyer';
            if (user) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                if (persistedRole && user.roles.includes(persistedRole)) {
                    role = persistedRole;
                } else {
                     if (user.roles.includes('admin')) role = 'admin';
                     else if (user.roles.includes('vendor')) role = 'vendor';
                     else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
                }
            }
            return { success: true, role }; 
          } catch (e: any) {
              return { success: false, error: e.message || "Login failed" };
          }
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           // Insert profile with phone number
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               phone_number: phoneNumber 
           });

           // Automatically log in after signup
           await login(email, password); 
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // 0. Update Profile Phone if provided
          if (data.phoneNumber) {
              await supabase.from('profiles').update({ phone_number: data.phoneNumber }).eq('id', currentUser.id);
          }

          // 1. Check if already registered
          const { data: existing } = await supabase
              .from('couriers')
              .select('id')
              .eq('user_id', currentUser.id)
              .maybeSingle();

          if (existing) {
              showToast("You are already registered as a courier.", "info");
              return { success: true };
          }

          // 2. Insert into 'couriers'.
          // Try inserting verified: false. This ensures default visibility as 'pending' in our new logic.
          const { error } = await supabase.from('couriers').insert({ 
              user_id: currentUser.id, 
              verified: false, 
              online_status: false,
              availability_status: 'unavailable'
          });

          if (error) {
              console.error("Delivery Registration Error:", error);
              throw error;
          }

          showToast("Rider application submitted", "success"); 
          await fetchData();
          return { success: true };
      } catch (err: any) {
          console.error("Exception during registration:", err);
          showToast(`Application failed: ${err.message || 'Unknown error'}`, "error");
          return { success: false };
      }
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found.", "error"); return false; }
      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const { error } = await supabase.from('products').update({ ...rest, contact_phone: contactPhone }).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);

              // Geo Logic: Resolve Coordinates for Map Routing
              // 1. Vendor Location
              const vendorCoords = vendor ? resolveCoordinates(vendor.location) : undefined;
              // 2. Buyer Location (Ideally from profile or input, defaulting to current GPS if user permitted it, or default cache)
              // For MVP, if we don't have user address input, we assume a central campus location or null
              const buyerCoords = currentUser.defaultLocation ? resolveCoordinates(currentUser.defaultLocation) : { lat: 5.6506, lng: -0.1962 };

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option,
                  // Save geospatial data for routing
                  pickup_coordinates: vendorCoords,
                  location_coordinates: buyerCoords
              });

              if (error) throw error;
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;

      try {
          // Concurrency Check: Ensure it wasn't just taken
          const { data: check } = await supabase.from('orders').select('delivery_person_id').eq('id', oid).single();
          if (check && check.delivery_person_id) {
              showToast("Job was just taken by another driver.", "error");
              await fetchData();
              return;
          }

          const { error } = await supabase
              .from('orders')
              .update({
                  delivery_person_id: currentUser.id,
                  status: 'courier_assigned'
              })
              .eq('id', oid);

          if (error) throw error;

          showToast("Job Accepted! Head to vendor.", "success");
          await fetchData();
      } catch (e: any) {
          console.error("Assign Error:", e);
          showToast("Failed to accept job.", "error");
      }
  };

  // Logistics
  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      // Find delivery profile ID
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      try {
          // Update 'couriers' table
          const { error } = await supabase.from('couriers').update({ online_status: isOnline }).eq('id', dProfile.id);
          if (error) throw error;
          await fetchData();
          showToast(isOnline ? "You are now ONLINE" : "You are now OFFLINE", "info");
      } catch(e) { console.error(e); }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser || currentRole !== 'deliveryPerson') return;
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      // 1. Database Update (Update 'couriers')
      supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id).then();

      // 2. Realtime Broadcast (Cheaper, faster for live tracking maps)
      const channel = supabase.channel(`courier_tracking:${dProfile.id}`);
      channel.subscribe((status) => {
          if (status === 'SUBSCRIBED') {
              channel.send({
                  type: 'broadcast',
                  event: 'location',
                  payload: { lat, lng, courierId: dProfile.id }
              });
          }
      });
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);
      if (!vendor) return;
      try {
          let query = vendor.id 
             ? supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id)
             : supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          const { error } = await query;
          if (error) throw error;
          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: 'approved' | 'rejected' | 'suspended') => { 
      try {
          // Update 'couriers' table using verified status mapping.

          let isVerified: boolean | null = false;
          let newStatus = 'pending'; // Optional status string if column exists

          if (status === 'approved') {
              isVerified = true;
              newStatus = 'approved';
          }
          else if (status === 'rejected' || status === 'suspended') {
              isVerified = false;
              newStatus = status;
          }

          // Try updating both verified and status (if status column exists in couriers)
          const { error: updateError } = await supabase.from('couriers').update({ verified: isVerified, status: newStatus }).eq('id', id);

          // If update fails (e.g., status column doesn't exist), fall back to just verified
          if (updateError && updateError.message?.includes('column "status" of relation "couriers" does not exist')) {
              await supabase.from('couriers').update({ verified: isVerified }).eq('id', id);
          } else if (updateError) {
              throw updateError;
          }

          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if (profile) {
               let roles = profile.roles || [];
               let changed = false;
               if (status === 'approved') {
                   if (!roles.includes('deliveryPerson')) { roles.push('deliveryPerson'); changed = true; }
               } else {
                   if (roles.includes('deliveryPerson')) { roles = roles.filter((r: string) => r !== 'deliveryPerson'); changed = true; }
               }
               if (changed) await supabase.from('profiles').update({ roles }).eq('id', uid);
          }
          showToast(`Rider ${status}`, "success");
          await fetchData(); 
      } catch (e: any) { showToast(`Failed: ${e.message}`, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, connectionError, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson> & { phoneNumber?: string }) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  // New Logistics
  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

// Coordinate Resolver Helper
const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    // Default fallback to Legon Campus center if completely unknown
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              // Enhanced Notification
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

                  // Vendor Alert
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              // Driver Alert
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as Order;
                  if (currentRoleRef.current === 'deliveryPerson' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.deliveryPersonId) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
              showToast("Connection failed. Please check your internet or API keys.", "error");
          }
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
          if (e.message !== "Vendor account pending approval" && e.message !== "Account Suspended") {
             // throw e; // don't rethrow to keep app alive
          }
      } 
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (error) throw error;

          if (data) {
              if (data.isBanned) {
                  throw new Error("Account Suspended");
              }

              if (data.roles?.includes('vendor') && !data.roles.includes('admin')) {
                  const { data: v } = await supabase.from('vendors').select('is_approved').eq('user_id', userId).maybeSingle();
                  if (v && v.is_approved === false) {
                       throw new Error("Vendor account pending approval");
                  }
              }

              const user: User = { ...data, roles: data.roles || ['buyer'] };
              setCurrentUser(user);

              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
          if (e.message === "Account Suspended" || e.message === "Vendor account pending approval") {
               await supabase.auth.signOut();
               setCurrentUser(null);
               throw e; 
          }
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e) { 
                 console.error(`Fetch ${table} failed:`, e);
                 return null;
             }
          };

          // Fetch tables individually.
          // Explicitly using 'couriers' table
          const [pData, vData, oData, dDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('couriers') 
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
                  locationCoordinates: o.locationCoordinates || o.location_coordinates,
                  pickupCoordinates: o.pickupCoordinates || o.pickup_coordinates,
              })) as Order[]);
          }

          // Manual Join for Couriers + Profiles
          // This fetches profile info for each courier
          let dData = dDataRaw;
          if (dDataRaw && dDataRaw.length > 0) {
              try {
                  const userIds = [...new Set(dDataRaw.map((d: any) => d.user_id).filter(Boolean))];
                  if (userIds.length > 0) {
                      const { data: profiles } = await supabase
                          .from('profiles')
                          .select('id, name, email')
                          .in('id', userIds);

                      if (profiles) {
                          const profileMap = new Map(profiles.map((p: any) => [p.id, p]));
                          dData = dDataRaw.map((d: any) => ({
                              ...d,
                              profiles: profileMap.get(d.user_id) || {}
                          }));
                      }
                  }
              } catch (err) {
                  console.error("Manual profile join failed for couriers", err);
              }
          }

          if (dData) setDeliveryPersons(dData.map((d: any) => {
             const profile = d.profiles || {}; 
             // Use d.full_name from couriers table if available, fallback to profile name
             const name = profile.name || d.full_name || 'Courier';

             // LOGIC: Map 'verified' boolean to 'status' string
             // Null/Undefined/False -> 'pending' (Visibility Fix: Treat false as pending so Admins see them)
             // True -> 'approved'

             let derivedStatus: 'pending' | 'approved' | 'rejected' | 'suspended' = 'pending';
             if (d.verified === true) derivedStatus = 'approved';
             else derivedStatus = 'pending';

             // Override with explicit status column if available and valid
             if (d.status && ['approved', 'rejected', 'suspended'].includes(d.status)) {
                 derivedStatus = d.status as any;
             }

             return {
                 ...d,
                 id: d.id,
                 userId: d.user_id,
                 fullName: name, // From profiles or direct
                 vehicleType: d.vehicle_type || 'Motorbike', 

                 onlineStatus: d.online_status, 
                 currentLat: d.current_lat,
                 currentLng: d.current_lng,
                 availabilityStatus: d.availability_status,
                 verified: d.verified,

                 status: derivedStatus,
                 rating: d.delivery_rating || 5.0
             };
          }) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }

          setConnectionError(false); 
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
          }
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      // Login attempt logic simplified to avoid pre-check which may fail due to RLS
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
           return { success: false, error: error.message === "Invalid login credentials" ? "Invalid email or password" : error.message };
      }

      if (data.user) {
          try {
            const user = await fetchUserProfile(data.user.id);
            if (!user) return { success: false, error: "Account profile missing. Please contact support." };

            fetchData();

            let role: Role = 'buyer';
            if (user) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                if (persistedRole && user.roles.includes(persistedRole)) {
                    role = persistedRole;
                } else {
                     if (user.roles.includes('admin')) role = 'admin';
                     else if (user.roles.includes('vendor')) role = 'vendor';
                     else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
                }
            }
            return { success: true, role }; 
          } catch (e: any) {
              return { success: false, error: e.message || "Login failed" };
          }
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           // Insert profile with phone number
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               phone_number: phoneNumber 
           });

           // Automatically log in after signup
           await login(email, password); 
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // 0. Update Profile Phone if provided
          if (data.phoneNumber) {
              await supabase.from('profiles').update({ phone_number: data.phoneNumber }).eq('id', currentUser.id);
          }

          // 1. Check if already registered
          const { data: existing } = await supabase
              .from('couriers')
              .select('id')
              .eq('user_id', currentUser.id)
              .maybeSingle();

          if (existing) {
              showToast("You are already registered as a courier.", "info");
              return { success: true };
          }

          // 2. Insert into 'couriers'.
          // Includes full_name and vehicle_type for easier DB identification
          const { error } = await supabase.from('couriers').insert({ 
              user_id: currentUser.id, 
              verified: false, 
              online_status: false,
              availability_status: 'unavailable',
              full_name: data.fullName || currentUser.name,
              vehicle_type: data.vehicleType || 'bicycle'
          });

          if (error) {
              console.error("Delivery Registration Error:", error);
              throw error;
          }

          showToast("Rider application submitted", "success"); 
          await fetchData();
          return { success: true };
      } catch (err: any) {
          console.error("Exception during registration:", err);
          showToast(`Application failed: ${err.message || 'Unknown error'}`, "error");
          return { success: false };
      }
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found.", "error"); return false; }
      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const { error } = await supabase.from('products').update({ ...rest, contact_phone: contactPhone }).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);

              // Geo Logic: Resolve Coordinates for Map Routing
              // 1. Vendor Location
              const vendorCoords = vendor ? resolveCoordinates(vendor.location) : undefined;
              // 2. Buyer Location (Ideally from profile or input, defaulting to current GPS if user permitted it, or default cache)
              // For MVP, if we don't have user address input, we assume a central campus location or null
              const buyerCoords = currentUser.defaultLocation ? resolveCoordinates(currentUser.defaultLocation) : { lat: 5.6506, lng: -0.1962 };

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option,
                  // Save geospatial data for routing
                  pickup_coordinates: vendorCoords,
                  location_coordinates: buyerCoords
              });

              if (error) throw error;
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;

      try {
          // Concurrency Check: Ensure it wasn't just taken
          const { data: check } = await supabase.from('orders').select('delivery_person_id').eq('id', oid).single();
          if (check && check.delivery_person_id) {
              showToast("Job was just taken by another driver.", "error");
              await fetchData();
              return;
          }

          const { error } = await supabase
              .from('orders')
              .update({
                  delivery_person_id: currentUser.id,
                  status: 'courier_assigned'
              })
              .eq('id', oid);

          if (error) throw error;

          showToast("Job Accepted! Head to vendor.", "success");
          await fetchData();
      } catch (e: any) {
          console.error("Assign Error:", e);
          showToast("Failed to accept job.", "error");
      }
  };

  // Logistics
  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      // Find delivery profile ID
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      try {
          // Update 'couriers' table
          const { error } = await supabase.from('couriers').update({ online_status: isOnline }).eq('id', dProfile.id);
          if (error) throw error;
          await fetchData();
          showToast(isOnline ? "You are now ONLINE" : "You are now OFFLINE", "info");
      } catch(e) { console.error(e); }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser || currentRole !== 'deliveryPerson') return;
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      // 1. Database Update (Update 'couriers')
      supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id).then();

      // 2. Realtime Broadcast (Cheaper, faster for live tracking maps)
      const channel = supabase.channel(`courier_tracking:${dProfile.id}`);
      channel.subscribe((status) => {
          if (status === 'SUBSCRIBED') {
              channel.send({
                  type: 'broadcast',
                  event: 'location',
                  payload: { lat, lng, courierId: dProfile.id }
              });
          }
      });
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);
      if (!vendor) return;
      try {
          let query = vendor.id 
             ? supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id)
             : supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          const { error } = await query;
          if (error) throw error;
          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: 'approved' | 'rejected' | 'suspended') => { 
      try {
          // Update 'couriers' table using verified status mapping.

          let isVerified: boolean | null = false;
          let newStatus = 'pending'; // Optional status string if column exists

          if (status === 'approved') {
              isVerified = true;
              newStatus = 'approved';
          }
          else if (status === 'rejected' || status === 'suspended') {
              isVerified = false;
              newStatus = status;
          }

          // Try updating both verified and status (if status column exists in couriers)
          const { error: updateError } = await supabase.from('couriers').update({ verified: isVerified, status: newStatus }).eq('id', id);

          // If update fails (e.g., status column doesn't exist), fall back to just verified
          if (updateError && updateError.message?.includes('column "status" of relation "couriers" does not exist')) {
              await supabase.from('couriers').update({ verified: isVerified }).eq('id', id);
          } else if (updateError) {
              throw updateError;
          }

          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if (profile) {
               let roles = profile.roles || [];
               let changed = false;
               if (status === 'approved') {
                   if (!roles.includes('deliveryPerson')) { roles.push('deliveryPerson'); changed = true; }
               } else {
                   if (roles.includes('deliveryPerson')) { roles = roles.filter((r: string) => r !== 'deliveryPerson'); changed = true; }
               }
               if (changed) await supabase.from('profiles').update({ roles }).eq('id', uid);
          }
          showToast(`Rider ${status}`, "success");
          await fetchData(); 
      } catch (e: any) { showToast(`Failed: ${e.message}`, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, connectionError, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson> & { phoneNumber?: string }) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  // New Logistics
  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

// Coordinate Resolver Helper
const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    // Default fallback to Legon Campus center if completely unknown
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              // Enhanced Notification
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

                  // Vendor Alert
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              // Driver Alert
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as Order;
                  if (currentRoleRef.current === 'deliveryPerson' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.deliveryPersonId) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
              showToast("Connection failed. Please check your internet or API keys.", "error");
          }
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
          if (e.message !== "Vendor account pending approval" && e.message !== "Account Suspended") {
             // throw e; // don't rethrow to keep app alive
          }
      } 
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          // PGRST116 Fix: Use maybeSingle() instead of single()
          // This prevents crashing if the profile row is missing (e.g., registration race condition)
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();

          if (error) throw error;

          if (data) {
              if (data.isBanned) {
                  throw new Error("Account Suspended");
              }

              if (data.roles?.includes('vendor') && !data.roles.includes('admin')) {
                  const { data: v } = await supabase.from('vendors').select('is_approved').eq('user_id', userId).maybeSingle();
                  if (v && v.is_approved === false) {
                       throw new Error("Vendor account pending approval");
                  }
              }

              const user: User = { ...data, roles: data.roles || ['buyer'] };
              setCurrentUser(user);

              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          } else {
              // Profile row is missing.
              console.warn(`Profile missing for user ${userId}. Cleaning up session.`);
              await supabase.auth.signOut();
              setCurrentUser(null);
              return null;
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
          if (e.message === "Account Suspended" || e.message === "Vendor account pending approval") {
               await supabase.auth.signOut();
               setCurrentUser(null);
               throw e; 
          }
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e) { 
                 console.error(`Fetch ${table} failed:`, e);
                 return null;
             }
          };

          // Fetch tables individually.
          // Explicitly using 'couriers' table
          const [pData, vData, oData, dDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('couriers') 
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
                  locationCoordinates: o.locationCoordinates || o.location_coordinates,
                  pickupCoordinates: o.pickupCoordinates || o.pickup_coordinates,
              })) as Order[]);
          }

          // Manual Join for Couriers + Profiles
          // This fetches profile info for each courier
          let dData = dDataRaw;
          if (dDataRaw && dDataRaw.length > 0) {
              try {
                  const userIds = [...new Set(dDataRaw.map((d: any) => d.user_id).filter(Boolean))];
                  if (userIds.length > 0) {
                      const { data: profiles } = await supabase
                          .from('profiles')
                          .select('id, name, email')
                          .in('id', userIds);

                      if (profiles) {
                          const profileMap = new Map(profiles.map((p: any) => [p.id, p]));
                          dData = dDataRaw.map((d: any) => ({
                              ...d,
                              profiles: profileMap.get(d.user_id) || {}
                          }));
                      }
                  }
              } catch (err) {
                  console.error("Manual profile join failed for couriers", err);
              }
          }

          if (dData) setDeliveryPersons(dData.map((d: any) => {
             const profile = d.profiles || {}; 
             // Use d.full_name from couriers table if available, fallback to profile name
             const name = profile.name || d.full_name || 'Courier';

             // LOGIC: Map 'verified' boolean to 'status' string
             // Null/Undefined/False -> 'pending' (Visibility Fix: Treat false as pending so Admins see them)
             // True -> 'approved'

             let derivedStatus: 'pending' | 'approved' | 'rejected' | 'suspended' = 'pending';
             if (d.verified === true) derivedStatus = 'approved';
             else derivedStatus = 'pending';

             // Override with explicit status column if available and valid
             if (d.status && ['approved', 'rejected', 'suspended'].includes(d.status)) {
                 derivedStatus = d.status as any;
             }

             return {
                 ...d,
                 id: d.id,
                 userId: d.user_id,
                 fullName: name, // From profiles or direct
                 vehicleType: d.vehicle_type || 'Motorbike', 

                 onlineStatus: d.online_status, 
                 currentLat: d.current_lat,
                 currentLng: d.current_lng,
                 availabilityStatus: d.availability_status,
                 verified: d.verified,

                 status: derivedStatus,
                 rating: d.delivery_rating || 5.0
             };
          }) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }

          setConnectionError(false); 
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
          }
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      // Login attempt logic simplified to avoid pre-check which may fail due to RLS
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
           return { success: false, error: error.message === "Invalid login credentials" ? "Invalid email or password" : error.message };
      }

      if (data.user) {
          try {
            const user = await fetchUserProfile(data.user.id);
            if (!user) return { success: false, error: "Account profile missing. Please contact support." };

            fetchData();

            let role: Role = 'buyer';
            if (user) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                if (persistedRole && user.roles.includes(persistedRole)) {
                    role = persistedRole;
                } else {
                     if (user.roles.includes('admin')) role = 'admin';
                     else if (user.roles.includes('vendor')) role = 'vendor';
                     else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
                }
            }
            return { success: true, role }; 
          } catch (e: any) {
              return { success: false, error: e.message || "Login failed" };
          }
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           // Insert profile with phone number
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               phone_number: phoneNumber 
           });

           // Automatically log in after signup
           await login(email, password); 
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // 0. Update Profile Phone if provided
          if (data.phoneNumber) {
              await supabase.from('profiles').update({ phone_number: data.phoneNumber }).eq('id', currentUser.id);
          }

          // 1. Check if already registered
          const { data: existing } = await supabase
              .from('couriers')
              .select('id')
              .eq('user_id', currentUser.id)
              .maybeSingle();

          if (existing) {
              showToast("You are already registered as a courier.", "info");
              return { success: true };
          }

          // 2. Insert into 'couriers'.
          // Includes full_name and vehicle_type for easier DB identification
          const { error } = await supabase.from('couriers').insert({ 
              user_id: currentUser.id, 
              verified: false, 
              online_status: false,
              availability_status: 'unavailable',
              full_name: data.fullName || currentUser.name,
              vehicle_type: data.vehicleType || 'bicycle'
          });

          if (error) {
              console.error("Delivery Registration Error:", error);
              throw error;
          }

          showToast("Rider application submitted", "success"); 
          await fetchData();
          return { success: true };
      } catch (err: any) {
          console.error("Exception during registration:", err);
          showToast(`Application failed: ${err.message || 'Unknown error'}`, "error");
          return { success: false };
      }
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found.", "error"); return false; }
      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const { error } = await supabase.from('products').update({ ...rest, contact_phone: contactPhone }).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);

              // Geo Logic: Resolve Coordinates for Map Routing
              // 1. Vendor Location
              const vendorCoords = vendor ? resolveCoordinates(vendor.location) : undefined;
              // 2. Buyer Location (Ideally from profile or input, defaulting to current GPS if user permitted it, or default cache)
              // For MVP, if we don't have user address input, we assume a central campus location or null
              const buyerCoords = currentUser.defaultLocation ? resolveCoordinates(currentUser.defaultLocation) : { lat: 5.6506, lng: -0.1962 };

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option,
                  // Save geospatial data for routing
                  pickup_coordinates: vendorCoords,
                  location_coordinates: buyerCoords
              });

              if (error) throw error;
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;

      try {
          // Concurrency Check: Ensure it wasn't just taken
          const { data: check } = await supabase.from('orders').select('delivery_person_id').eq('id', oid).single();
          if (check && check.delivery_person_id) {
              showToast("Job was just taken by another driver.", "error");
              await fetchData();
              return;
          }

          const { error } = await supabase
              .from('orders')
              .update({
                  delivery_person_id: currentUser.id,
                  status: 'courier_assigned'
              })
              .eq('id', oid);

          if (error) throw error;

          showToast("Job Accepted! Head to vendor.", "success");
          await fetchData();
      } catch (e: any) {
          console.error("Assign Error:", e);
          showToast("Failed to accept job.", "error");
      }
  };

  // Logistics
  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      // Find delivery profile ID
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      try {
          // Update 'couriers' table
          const { error } = await supabase.from('couriers').update({ online_status: isOnline }).eq('id', dProfile.id);
          if (error) throw error;
          await fetchData();
          showToast(isOnline ? "You are now ONLINE" : "You are now OFFLINE", "info");
      } catch(e) { console.error(e); }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser || currentRole !== 'deliveryPerson') return;
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      // 1. Database Update (Update 'couriers')
      supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id).then();

      // 2. Realtime Broadcast (Cheaper, faster for live tracking maps)
      const channel = supabase.channel(`courier_tracking:${dProfile.id}`);
      channel.subscribe((status) => {
          if (status === 'SUBSCRIBED') {
              channel.send({
                  type: 'broadcast',
                  event: 'location',
                  payload: { lat, lng, courierId: dProfile.id }
              });
          }
      });
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);
      if (!vendor) return;
      try {
          let query = vendor.id 
             ? supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id)
             : supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          const { error } = await query;
          if (error) throw error;
          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: 'approved' | 'rejected' | 'suspended') => { 
      try {
          // Update 'couriers' table using verified status mapping.

          let isVerified: boolean | null = false;
          let newStatus = 'pending'; // Optional status string if column exists

          if (status === 'approved') {
              isVerified = true;
              newStatus = 'approved';
          }
          else if (status === 'rejected' || status === 'suspended') {
              isVerified = false;
              newStatus = status;
          }

          // Try updating both verified and status (if status column exists in couriers)
          const { error: updateError } = await supabase.from('couriers').update({ verified: isVerified, status: newStatus }).eq('id', id);

          // If update fails (e.g., status column doesn't exist), fall back to just verified
          if (updateError && updateError.message?.includes('column "status" of relation "couriers" does not exist')) {
              await supabase.from('couriers').update({ verified: isVerified }).eq('id', id);
          } else if (updateError) {
              throw updateError;
          }

          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if (profile) {
               let roles = profile.roles || [];
               let changed = false;
               if (status === 'approved') {
                   if (!roles.includes('deliveryPerson')) { roles.push('deliveryPerson'); changed = true; }
               } else {
                   if (roles.includes('deliveryPerson')) { roles = roles.filter((r: string) => r !== 'deliveryPerson'); changed = true; }
               }
               if (changed) await supabase.from('profiles').update({ roles }).eq('id', uid);
          }
          showToast(`Rider ${status}`, "success");
          await fetchData(); 
      } catch (e: any) { showToast(`Failed: ${e.message}`, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, connectionError, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson> & { phoneNumber?: string }) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  // New Logistics
  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

// Coordinate Resolver Helper
const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    // Default fallback to Legon Campus center if completely unknown
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              // Enhanced Notification
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

                  // Vendor Alert
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              // Driver Alert
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as Order;
                  if (currentRoleRef.current === 'deliveryPerson' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.deliveryPersonId) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
              showToast("Connection failed. Please check your internet or API keys.", "error");
          }
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id, data.session.user);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
          if (e.message !== "Vendor account pending approval" && e.message !== "Account Suspended") {
             // throw e; // don't rethrow to keep app alive
          }
      } 
  };

  const fetchUserProfile = async (userId: string, sessionUser?: any) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          // PGRST116 Fix: Use maybeSingle() instead of single()
          // This prevents crashing if the profile row is missing (e.g., registration race condition)
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();

          if (error) throw error;

          if (data) {
              if (data.isBanned) {
                  throw new Error("Account Suspended");
              }

              if (data.roles?.includes('vendor') && !data.roles.includes('admin')) {
                  const { data: v } = await supabase.from('vendors').select('is_approved').eq('user_id', userId).maybeSingle();
                  if (v && v.is_approved === false) {
                       throw new Error("Vendor account pending approval");
                  }
              }

              const user: User = { ...data, roles: data.roles || ['buyer'] };
              setCurrentUser(user);

              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          } else {
              // Profile row is missing.
              // AUTO-RECOVERY: If we have session details, recreate the profile row.
              if (sessionUser) {
                  console.warn(`Profile missing for user ${userId}. Attempting auto-recovery...`);
                  const { error: insertError } = await supabase.from('profiles').insert({
                      id: userId,
                      email: sessionUser.email,
                      name: sessionUser.user_metadata?.full_name || sessionUser.email?.split('@')[0] || 'Restored User',
                      roles: ['buyer']
                  });

                  if (!insertError) {
                      showToast("Profile restored automatically", "success");
                      // Retry fetch with the new data (pass undefined for sessionUser to avoid infinite loop risk, though rare)
                      return fetchUserProfile(userId, undefined);
                  } else {
                      console.error("Auto-recovery failed:", insertError);
                  }
              }

              console.warn(`Profile missing for user ${userId}. Cleaning up session.`);
              await supabase.auth.signOut();
              setCurrentUser(null);
              return null;
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
          if (e.message === "Account Suspended" || e.message === "Vendor account pending approval") {
               await supabase.auth.signOut();
               setCurrentUser(null);
               throw e; 
          }
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e) { 
                 console.error(`Fetch ${table} failed:`, e);
                 return null;
             }
          };

          // Fetch tables individually.
          // Explicitly using 'couriers' table
          const [pData, vData, oData, dDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('couriers') 
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
                  locationCoordinates: o.locationCoordinates || o.location_coordinates,
                  pickupCoordinates: o.pickupCoordinates || o.pickup_coordinates,
              })) as Order[]);
          }

          // Manual Join for Couriers + Profiles
          // This fetches profile info for each courier
          let dData = dDataRaw;
          if (dDataRaw && dDataRaw.length > 0) {
              try {
                  const userIds = [...new Set(dDataRaw.map((d: any) => d.user_id).filter(Boolean))];
                  if (userIds.length > 0) {
                      const { data: profiles } = await supabase
                          .from('profiles')
                          .select('id, name, email')
                          .in('id', userIds);

                      if (profiles) {
                          const profileMap = new Map(profiles.map((p: any) => [p.id, p]));
                          dData = dDataRaw.map((d: any) => ({
                              ...d,
                              profiles: profileMap.get(d.user_id) || {}
                          }));
                      }
                  }
              } catch (err) {
                  console.error("Manual profile join failed for couriers", err);
              }
          }

          if (dData) setDeliveryPersons(dData.map((d: any) => {
             const profile = d.profiles || {}; 
             // Use d.full_name from couriers table if available, fallback to profile name
             const name = profile.name || d.full_name || 'Courier';

             // LOGIC: Map 'verified' boolean to 'status' string
             // Null/Undefined/False -> 'pending' (Visibility Fix: Treat false as pending so Admins see them)
             // True -> 'approved'

             let derivedStatus: 'pending' | 'approved' | 'rejected' | 'suspended' = 'pending';
             if (d.verified === true) derivedStatus = 'approved';
             else derivedStatus = 'pending';

             // Override with explicit status column if available and valid
             if (d.status && ['approved', 'rejected', 'suspended'].includes(d.status)) {
                 derivedStatus = d.status as any;
             }

             return {
                 ...d,
                 id: d.id,
                 userId: d.user_id,
                 fullName: name, // From profiles or direct
                 vehicleType: d.vehicle_type || 'Motorbike', 

                 onlineStatus: d.online_status, 
                 currentLat: d.current_lat,
                 currentLng: d.current_lng,
                 availabilityStatus: d.availability_status,
                 verified: d.verified,

                 status: derivedStatus,
                 rating: d.delivery_rating || 5.0
             };
          }) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }

          setConnectionError(false); 
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
          }
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      // Login attempt logic simplified to avoid pre-check which may fail due to RLS
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
           return { success: false, error: error.message === "Invalid login credentials" ? "Invalid email or password" : error.message };
      }

      if (data.user) {
          try {
            // Pass the user object to enable auto-recovery if profile is missing
            const user = await fetchUserProfile(data.user.id, data.user);
            if (!user) return { success: false, error: "Account profile missing. Please contact support." };

            fetchData();

            let role: Role = 'buyer';
            if (user) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                if (persistedRole && user.roles.includes(persistedRole)) {
                    role = persistedRole;
                } else {
                     if (user.roles.includes('admin')) role = 'admin';
                     else if (user.roles.includes('vendor')) role = 'vendor';
                     else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
                }
            }
            return { success: true, role }; 
          } catch (e: any) {
              return { success: false, error: e.message || "Login failed" };
          }
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           // Insert profile with phone number
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               phone_number: phoneNumber 
           });

           // Automatically log in after signup
           await login(email, password); 
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // 0. Update Profile Phone if provided
          if (data.phoneNumber) {
              await supabase.from('profiles').update({ phone_number: data.phoneNumber }).eq('id', currentUser.id);
          }

          // 1. Check if already registered
          const { data: existing } = await supabase
              .from('couriers')
              .select('id')
              .eq('user_id', currentUser.id)
              .maybeSingle();

          if (existing) {
              showToast("You are already registered as a courier.", "info");
              return { success: true };
          }

          // 2. Insert into 'couriers'.
          // Includes full_name and vehicle_type for easier DB identification
          const { error } = await supabase.from('couriers').insert({ 
              user_id: currentUser.id, 
              verified: false, 
              online_status: false,
              availability_status: 'unavailable',
              full_name: data.fullName || currentUser.name,
              vehicle_type: data.vehicleType || 'bicycle'
          });

          if (error) {
              console.error("Delivery Registration Error:", error);
              throw error;
          }

          showToast("Rider application submitted", "success"); 
          await fetchData();
          return { success: true };
      } catch (err: any) {
          console.error("Exception during registration:", err);
          showToast(`Application failed: ${err.message || 'Unknown error'}`, "error");
          return { success: false };
      }
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found.", "error"); return false; }
      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const { error } = await supabase.from('products').update({ ...rest, contact_phone: contactPhone }).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);

              // Geo Logic: Resolve Coordinates for Map Routing
              // 1. Vendor Location
              const vendorCoords = vendor ? resolveCoordinates(vendor.location) : undefined;
              // 2. Buyer Location (Ideally from profile or input, defaulting to current GPS if user permitted it, or default cache)
              // For MVP, if we don't have user address input, we assume a central campus location or null
              const buyerCoords = currentUser.defaultLocation ? resolveCoordinates(currentUser.defaultLocation) : { lat: 5.6506, lng: -0.1962 };

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option,
                  // Save geospatial data for routing
                  pickup_coordinates: vendorCoords,
                  location_coordinates: buyerCoords
              });

              if (error) throw error;
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;

      try {
          // Concurrency Check: Ensure it wasn't just taken
          const { data: check } = await supabase.from('orders').select('delivery_person_id').eq('id', oid).single();
          if (check && check.delivery_person_id) {
              showToast("Job was just taken by another driver.", "error");
              await fetchData();
              return;
          }

          const { error } = await supabase
              .from('orders')
              .update({
                  delivery_person_id: currentUser.id,
                  status: 'courier_assigned'
              })
              .eq('id', oid);

          if (error) throw error;

          showToast("Job Accepted! Head to vendor.", "success");
          await fetchData();
      } catch (e: any) {
          console.error("Assign Error:", e);
          showToast("Failed to accept job.", "error");
      }
  };

  // Logistics
  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      // Find delivery profile ID
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      try {
          // Update 'couriers' table
          const { error } = await supabase.from('couriers').update({ online_status: isOnline }).eq('id', dProfile.id);
          if (error) throw error;
          await fetchData();
          showToast(isOnline ? "You are now ONLINE" : "You are now OFFLINE", "info");
      } catch(e) { console.error(e); }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser || currentRole !== 'deliveryPerson') return;
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      // 1. Database Update (Update 'couriers')
      supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id).then();

      // 2. Realtime Broadcast (Cheaper, faster for live tracking maps)
      const channel = supabase.channel(`courier_tracking:${dProfile.id}`);
      channel.subscribe((status) => {
          if (status === 'SUBSCRIBED') {
              channel.send({
                  type: 'broadcast',
                  event: 'location',
                  payload: { lat, lng, courierId: dProfile.id }
              });
          }
      });
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);
      if (!vendor) return;
      try {
          let query = vendor.id 
             ? supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id)
             : supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          const { error } = await query;
          if (error) throw error;
          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: 'approved' | 'rejected' | 'suspended') => { 
      try {
          // Update 'couriers' table using verified status mapping.

          let isVerified: boolean | null = false;
          let newStatus = 'pending'; // Optional status string if column exists

          if (status === 'approved') {
              isVerified = true;
              newStatus = 'approved';
          }
          else if (status === 'rejected' || status === 'suspended') {
              isVerified = false;
              newStatus = status;
          }

          // Try updating both verified and status (if status column exists in couriers)
          const { error: updateError } = await supabase.from('couriers').update({ verified: isVerified, status: newStatus }).eq('id', id);

          // If update fails (e.g., status column doesn't exist), fall back to just verified
          if (updateError && updateError.message?.includes('column "status" of relation "couriers" does not exist')) {
              await supabase.from('couriers').update({ verified: isVerified }).eq('id', id);
          } else if (updateError) {
              throw updateError;
          }

          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if (profile) {
               let roles = profile.roles || [];
               let changed = false;
               if (status === 'approved') {
                   if (!roles.includes('deliveryPerson')) { roles.push('deliveryPerson'); changed = true; }
               } else {
                   if (roles.includes('deliveryPerson')) { roles = roles.filter((r: string) => r !== 'deliveryPerson'); changed = true; }
               }
               if (changed) await supabase.from('profiles').update({ roles }).eq('id', uid);
          }
          showToast(`Rider ${status}`, "success");
          await fetchData(); 
      } catch (e: any) { showToast(`Failed: ${e.message}`, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, connectionError, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson> & { phoneNumber?: string }) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  // New Logistics
  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

// Coordinate Resolver Helper
const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    // Default fallback to Legon Campus center if completely unknown
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              // Enhanced Notification
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

                  // Vendor Alert
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              // Driver Alert
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as Order;
                  if (currentRoleRef.current === 'deliveryPerson' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.deliveryPersonId) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
              showToast("Connection failed. Please check your internet or API keys.", "error");
          }
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id, data.session.user);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
          if (e.message !== "Vendor account pending approval" && e.message !== "Account Suspended") {
             // throw e; // don't rethrow to keep app alive
          }
      } 
  };

  const fetchUserProfile = async (userId: string, sessionUser?: any) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          // PGRST116 Fix: Use maybeSingle() instead of single()
          // This prevents crashing if the profile row is missing (e.g., registration race condition)
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();

          if (error) throw error;

          if (data) {
              if (data.isBanned) {
                  throw new Error("Account Suspended");
              }

              if (data.roles?.includes('vendor') && !data.roles.includes('admin')) {
                  const { data: v } = await supabase.from('vendors').select('is_approved').eq('user_id', userId).maybeSingle();
                  if (v && v.is_approved === false) {
                       throw new Error("Vendor account pending approval");
                  }
              }

              const user: User = { ...data, roles: data.roles || ['buyer'] };
              setCurrentUser(user);

              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          } else {
              // Profile row is missing.
              // AUTO-RECOVERY: If we have session details, recreate the profile row.
              if (sessionUser) {
                  console.warn(`Profile missing for user ${userId}. Attempting auto-recovery...`);
                  const { error: insertError } = await supabase.from('profiles').insert({
                      id: userId,
                      email: sessionUser.email,
                      name: sessionUser.user_metadata?.full_name || sessionUser.email?.split('@')[0] || 'Restored User',
                      roles: ['buyer']
                  });

                  if (!insertError) {
                      showToast("Profile restored automatically", "success");
                      // Retry fetch with the new data (pass undefined for sessionUser to avoid infinite loop risk, though rare)
                      return fetchUserProfile(userId, undefined);
                  } else {
                      console.error("Auto-recovery failed:", insertError);
                  }
              }

              console.warn(`Profile missing for user ${userId}. Cleaning up session.`);
              await supabase.auth.signOut();
              setCurrentUser(null);
              return null;
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
          if (e.message === "Account Suspended" || e.message === "Vendor account pending approval") {
               await supabase.auth.signOut();
               setCurrentUser(null);
               throw e; 
          }
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e) { 
                 console.error(`Fetch ${table} failed:`, e);
                 return null;
             }
          };

          // Fetch tables individually.
          // FIX: Changed 'couriers' to 'delivery_persons' to match README schema
          const [pData, vData, oData, dDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('delivery_persons') 
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
                  locationCoordinates: o.locationCoordinates || o.location_coordinates,
                  pickupCoordinates: o.pickupCoordinates || o.pickup_coordinates,
              })) as Order[]);
          }

          // Manual Join for Profiles
          let dData = dDataRaw;
          if (dDataRaw && dDataRaw.length > 0) {
              try {
                  const userIds = [...new Set(dDataRaw.map((d: any) => d.user_id).filter(Boolean))];
                  if (userIds.length > 0) {
                      const { data: profiles } = await supabase
                          .from('profiles')
                          .select('id, name, email')
                          .in('id', userIds);

                      if (profiles) {
                          const profileMap = new Map(profiles.map((p: any) => [p.id, p]));
                          dData = dDataRaw.map((d: any) => ({
                              ...d,
                              profiles: profileMap.get(d.user_id) || {}
                          }));
                      }
                  }
              } catch (err) {
                  console.error("Manual profile join failed for delivery persons", err);
              }
          }

          if (dData) setDeliveryPersons(dData.map((d: any) => {
             const profile = d.profiles || {}; 
             // Use d.full_name from table if available, fallback to profile name
             const name = profile.name || d.full_name || 'Courier';

             return {
                 ...d,
                 id: d.id,
                 userId: d.user_id,
                 fullName: name, // From profiles or direct
                 vehicleType: d.vehicle_type || 'Motorbike', 

                 // Handle potentially missing columns gracefully
                 onlineStatus: d.online_status ?? false, 
                 currentLat: d.current_lat,
                 currentLng: d.current_lng,
                 availabilityStatus: d.availability_status,
                 verified: d.status === 'approved',

                 status: d.status || 'pending',
                 rating: d.delivery_rating || d.rating || 5.0
             };
          }) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }

          setConnectionError(false); 
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
          }
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
           return { success: false, error: error.message === "Invalid login credentials" ? "Invalid email or password" : error.message };
      }

      if (data.user) {
          try {
            const user = await fetchUserProfile(data.user.id, data.user);
            if (!user) return { success: false, error: "Account profile missing. Please contact support." };

            fetchData();

            let role: Role = 'buyer';
            if (user) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                if (persistedRole && user.roles.includes(persistedRole)) {
                    role = persistedRole;
                } else {
                     if (user.roles.includes('admin')) role = 'admin';
                     else if (user.roles.includes('vendor')) role = 'vendor';
                     else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
                }
            }
            return { success: true, role }; 
          } catch (e: any) {
              return { success: false, error: e.message || "Login failed" };
          }
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           // Insert profile with phone number
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               phone_number: phoneNumber 
           });

           // Automatically log in after signup
           await login(email, password); 
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // 0. Update Profile Phone if provided
          if (data.phoneNumber) {
              await supabase.from('profiles').update({ phone_number: data.phoneNumber }).eq('id', currentUser.id);
          }

          // FIX: Use 'delivery_persons' table (standard from README)
          const { data: existing } = await supabase
              .from('delivery_persons')
              .select('id')
              .eq('user_id', currentUser.id)
              .maybeSingle();

          if (existing) {
              showToast("You are already registered as a courier.", "info");
              return { success: true };
          }

          // 2. Insert into 'delivery_persons'
          const { error } = await supabase.from('delivery_persons').insert({ 
              user_id: currentUser.id, 
              status: 'pending', 
              full_name: data.fullName || currentUser.name,
              vehicle_type: data.vehicleType || 'bicycle'
          });

          if (error) {
              console.error("Delivery Registration Error:", error);
              throw error;
          }

          // 3. CRITICAL: Add role to profile immediately so they can access dashboard (where they see "Pending")
          if (!currentUser.roles.includes('deliveryPerson')) {
              const newRoles = [...currentUser.roles, 'deliveryPerson'];
              await supabase.from('profiles').update({ roles: newRoles }).eq('id', currentUser.id);
              // Update local state
              setCurrentUser({ ...currentUser, roles: newRoles });
          }

          showToast("Rider application submitted", "success"); 
          await fetchData();
          return { success: true };
      } catch (err: any) {
          console.error("Exception during registration:", err);
          showToast(`Application failed: ${err.message || 'Unknown error'}`, "error");
          return { success: false };
      }
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found.", "error"); return false; }
      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const { error } = await supabase.from('products').update({ ...rest, contact_phone: contactPhone }).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);

              // Geo Logic: Resolve Coordinates for Map Routing
              // 1. Vendor Location
              const vendorCoords = vendor ? resolveCoordinates(vendor.location) : undefined;
              // 2. Buyer Location (Ideally from profile or input, defaulting to current GPS if user permitted it, or default cache)
              // For MVP, if we don't have user address input, we assume a central campus location or null
              const buyerCoords = currentUser.defaultLocation ? resolveCoordinates(currentUser.defaultLocation) : { lat: 5.6506, lng: -0.1962 };

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option,
                  // Save geospatial data for routing
                  pickup_coordinates: vendorCoords,
                  location_coordinates: buyerCoords
              });

              if (error) throw error;
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;

      try {
          // Concurrency Check: Ensure it wasn't just taken
          const { data: check } = await supabase.from('orders').select('delivery_person_id').eq('id', oid).single();
          if (check && check.delivery_person_id) {
              showToast("Job was just taken by another driver.", "error");
              await fetchData();
              return;
          }

          const { error } = await supabase
              .from('orders')
              .update({
                  delivery_person_id: currentUser.id,
                  status: 'courier_assigned'
              })
              .eq('id', oid);

          if (error) throw error;

          showToast("Job Accepted! Head to vendor.", "success");
          await fetchData();
      } catch (e: any) {
          console.error("Assign Error:", e);
          showToast("Failed to accept job.", "error");
      }
  };

  // Logistics
  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      // Find delivery profile ID
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      try {
          // Update 'delivery_persons' table (FIX: using correct table name)
          const { error } = await supabase.from('delivery_persons').update({ online_status: isOnline }).eq('id', dProfile.id);
          if (error) {
              // Graceful degradation if column missing in DB
              console.warn("Could not update status in DB (column might be missing)", error);
          }
          await fetchData();
          showToast(isOnline ? "You are now ONLINE" : "You are now OFFLINE", "info");
      } catch(e) { console.error(e); }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser || currentRole !== 'deliveryPerson') return;
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      // 1. Database Update (Update 'delivery_persons' - FIX table name)
      // Note: This might fail if user hasn't added current_lat/lng columns, but we try anyway.
      supabase.from('delivery_persons').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id).then();

      // 2. Realtime Broadcast (Cheaper, faster for live tracking maps)
      const channel = supabase.channel(`courier_tracking:${dProfile.id}`);
      channel.subscribe((status) => {
          if (status === 'SUBSCRIBED') {
              channel.send({
                  type: 'broadcast',
                  event: 'location',
                  payload: { lat, lng, courierId: dProfile.id }
              });
          }
      });
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);
      if (!vendor) return;
      try {
          let query = vendor.id 
             ? supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id)
             : supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          const { error } = await query;
          if (error) throw error;
          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: 'approved' | 'rejected' | 'suspended') => { 
      try {
          // Update 'delivery_persons' table (FIX table name)
          const { error: updateError } = await supabase.from('delivery_persons').update({ status }).eq('id', id);
          if (updateError) throw updateError;

          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if (profile) {
               let roles = profile.roles || [];
               let changed = false;
               if (status === 'approved') {
                   if (!roles.includes('deliveryPerson')) { roles.push('deliveryPerson'); changed = true; }
               } else {
                   // Optional: Remove role if suspended? 
                   // For now, keep role so they can see dashboard "suspended" status
               }
               if (changed) await supabase.from('profiles').update({ roles }).eq('id', uid);
          }
          showToast(`Rider ${status}`, "success");
          await fetchData(); 
      } catch (e: any) { showToast(`Failed: ${e.message}`, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, connectionError, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson> & { phoneNumber?: string }) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  // New Logistics
  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

// Coordinate Resolver Helper
const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    // Default fallback to Legon Campus center if completely unknown
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              // Enhanced Notification
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

                  // Vendor Alert
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              // Driver Alert
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as Order;
                  if (currentRoleRef.current === 'deliveryPerson' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.deliveryPersonId) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
              showToast("Connection failed. Please check your internet or API keys.", "error");
          }
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id, data.session.user);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
          if (e.message !== "Vendor account pending approval" && e.message !== "Account Suspended") {
             // throw e; // don't rethrow to keep app alive
          }
      } 
  };

  const fetchUserProfile = async (userId: string, sessionUser?: any) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          // PGRST116 Fix: Use maybeSingle() instead of single()
          // This prevents crashing if the profile row is missing (e.g., registration race condition)
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();

          if (error) throw error;

          if (data) {
              if (data.isBanned) {
                  throw new Error("Account Suspended");
              }

              if (data.roles?.includes('vendor') && !data.roles.includes('admin')) {
                  const { data: v } = await supabase.from('vendors').select('is_approved').eq('user_id', userId).maybeSingle();
                  if (v && v.is_approved === false) {
                       throw new Error("Vendor account pending approval");
                  }
              }

              const user: User = { ...data, roles: data.roles || ['buyer'] };
              setCurrentUser(user);

              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          } else {
              // Profile row is missing.
              // AUTO-RECOVERY: If we have session details, recreate the profile row.
              if (sessionUser) {
                  console.warn(`Profile missing for user ${userId}. Attempting auto-recovery...`);
                  const { error: insertError } = await supabase.from('profiles').insert({
                      id: userId,
                      email: sessionUser.email,
                      name: sessionUser.user_metadata?.full_name || sessionUser.email?.split('@')[0] || 'Restored User',
                      roles: ['buyer']
                  });

                  if (!insertError) {
                      showToast("Profile restored automatically", "success");
                      // Retry fetch with the new data (pass undefined for sessionUser to avoid infinite loop risk, though rare)
                      return fetchUserProfile(userId, undefined);
                  } else {
                      console.error("Auto-recovery failed:", insertError);
                  }
              }

              console.warn(`Profile missing for user ${userId}. Cleaning up session.`);
              await supabase.auth.signOut();
              setCurrentUser(null);
              return null;
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
          if (e.message === "Account Suspended" || e.message === "Vendor account pending approval") {
               await supabase.auth.signOut();
               setCurrentUser(null);
               throw e; 
          }
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e) { 
                 console.error(`Fetch ${table} failed:`, e);
                 return null;
             }
          };

          // Fetch tables individually.
          // FIX: Changed 'couriers' to 'delivery_persons' to match README schema
          const [pData, vData, oData, dDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('delivery_persons') 
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
                  locationCoordinates: o.locationCoordinates || o.location_coordinates,
                  pickupCoordinates: o.pickupCoordinates || o.pickup_coordinates,
              })) as Order[]);
          }

          // Manual Join for Profiles
          let dData = dDataRaw;
          if (dDataRaw && dDataRaw.length > 0) {
              try {
                  const userIds = [...new Set(dDataRaw.map((d: any) => d.user_id).filter(Boolean))];
                  if (userIds.length > 0) {
                      const { data: profiles } = await supabase
                          .from('profiles')
                          .select('id, name, email')
                          .in('id', userIds);

                      if (profiles) {
                          const profileMap = new Map(profiles.map((p: any) => [p.id, p]));
                          dData = dDataRaw.map((d: any) => ({
                              ...d,
                              profiles: profileMap.get(d.user_id) || {}
                          }));
                      }
                  }
              } catch (err) {
                  console.error("Manual profile join failed for delivery persons", err);
              }
          }

          if (dData) setDeliveryPersons(dData.map((d: any) => {
             const profile = d.profiles || {}; 
             // Use d.full_name from table if available, fallback to profile name
             const name = profile.name || d.full_name || 'Courier';

             return {
                 ...d,
                 id: d.id,
                 userId: d.user_id,
                 fullName: name, // From profiles or direct
                 vehicleType: d.vehicle_type || 'Motorbike', 

                 // Handle potentially missing columns gracefully
                 onlineStatus: d.online_status ?? false, 
                 currentLat: d.current_lat,
                 currentLng: d.current_lng,
                 availabilityStatus: d.availability_status,
                 verified: d.status === 'approved',

                 status: d.status || 'pending',
                 rating: d.delivery_rating || d.rating || 5.0
             };
          }) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }

          setConnectionError(false); 
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
          }
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
           return { success: false, error: error.message === "Invalid login credentials" ? "Invalid email or password" : error.message };
      }

      if (data.user) {
          try {
            const user = await fetchUserProfile(data.user.id, data.user);
            if (!user) return { success: false, error: "Account profile missing. Please contact support." };

            fetchData();

            let role: Role = 'buyer';
            if (user) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                if (persistedRole && user.roles.includes(persistedRole)) {
                    role = persistedRole;
                } else {
                     if (user.roles.includes('admin')) role = 'admin';
                     else if (user.roles.includes('vendor')) role = 'vendor';
                     else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
                }
            }
            return { success: true, role }; 
          } catch (e: any) {
              return { success: false, error: e.message || "Login failed" };
          }
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           // Insert profile with phone number
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               phone_number: phoneNumber 
           });

           // Automatically log in after signup
           await login(email, password); 
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // 0. Update Profile Phone if provided
          if (data.phoneNumber) {
              await supabase.from('profiles').update({ phone_number: data.phoneNumber }).eq('id', currentUser.id);
          }

          // FIX: Use 'delivery_persons' table (standard from README)
          const { data: existing } = await supabase
              .from('delivery_persons')
              .select('id')
              .eq('user_id', currentUser.id)
              .maybeSingle();

          if (existing) {
              showToast("You are already registered as a courier.", "info");
              return { success: true };
          }

          // 2. Insert into 'delivery_persons'
          const { error } = await supabase.from('delivery_persons').insert({ 
              user_id: currentUser.id, 
              status: 'pending', 
              full_name: data.fullName || currentUser.name,
              vehicle_type: data.vehicleType || 'bicycle'
          });

          if (error) {
              console.error("Delivery Registration Error:", error);
              throw error;
          }

          // 3. CRITICAL: Add role to profile immediately so they can access dashboard (where they see "Pending")
          if (!currentUser.roles.includes('deliveryPerson')) {
              const newRoles: Role[] = [...currentUser.roles, 'deliveryPerson'];
              await supabase.from('profiles').update({ roles: newRoles }).eq('id', currentUser.id);
              // Update local state
              setCurrentUser({ ...currentUser, roles: newRoles });
          }

          showToast("Rider application submitted", "success"); 
          await fetchData();
          return { success: true };
      } catch (err: any) {
          console.error("Exception during registration:", err);
          showToast(`Application failed: ${err.message || 'Unknown error'}`, "error");
          return { success: false };
      }
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found.", "error"); return false; }
      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const { error } = await supabase.from('products').update({ ...rest, contact_phone: contactPhone }).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);

              // Geo Logic: Resolve Coordinates for Map Routing
              // 1. Vendor Location
              const vendorCoords = vendor ? resolveCoordinates(vendor.location) : undefined;
              // 2. Buyer Location (Ideally from profile or input, defaulting to current GPS if user permitted it, or default cache)
              // For MVP, if we don't have user address input, we assume a central campus location or null
              const buyerCoords = currentUser.defaultLocation ? resolveCoordinates(currentUser.defaultLocation) : { lat: 5.6506, lng: -0.1962 };

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option,
                  // Save geospatial data for routing
                  pickup_coordinates: vendorCoords,
                  location_coordinates: buyerCoords
              });

              if (error) throw error;
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;

      try {
          // Concurrency Check: Ensure it wasn't just taken
          const { data: check } = await supabase.from('orders').select('delivery_person_id').eq('id', oid).single();
          if (check && check.delivery_person_id) {
              showToast("Job was just taken by another driver.", "error");
              await fetchData();
              return;
          }

          const { error } = await supabase
              .from('orders')
              .update({
                  delivery_person_id: currentUser.id,
                  status: 'courier_assigned'
              })
              .eq('id', oid);

          if (error) throw error;

          showToast("Job Accepted! Head to vendor.", "success");
          await fetchData();
      } catch (e: any) {
          console.error("Assign Error:", e);
          showToast("Failed to accept job.", "error");
      }
  };

  // Logistics
  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      // Find delivery profile ID
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      try {
          // Update 'delivery_persons' table (FIX: using correct table name)
          const { error } = await supabase.from('delivery_persons').update({ online_status: isOnline }).eq('id', dProfile.id);
          if (error) {
              // Graceful degradation if column missing in DB
              console.warn("Could not update status in DB (column might be missing)", error);
          }
          await fetchData();
          showToast(isOnline ? "You are now ONLINE" : "You are now OFFLINE", "info");
      } catch(e) { console.error(e); }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser || currentRole !== 'deliveryPerson') return;
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      // 1. Database Update (Update 'delivery_persons' - FIX table name)
      // Note: This might fail if user hasn't added current_lat/lng columns, but we try anyway.
      supabase.from('delivery_persons').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id).then();

      // 2. Realtime Broadcast (Cheaper, faster for live tracking maps)
      const channel = supabase.channel(`courier_tracking:${dProfile.id}`);
      channel.subscribe((status) => {
          if (status === 'SUBSCRIBED') {
              channel.send({
                  type: 'broadcast',
                  event: 'location',
                  payload: { lat, lng, courierId: dProfile.id }
              });
          }
      });
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);
      if (!vendor) return;
      try {
          let query = vendor.id 
             ? supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id)
             : supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          const { error } = await query;
          if (error) throw error;
          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: 'approved' | 'rejected' | 'suspended') => { 
      try {
          // Update 'delivery_persons' table (FIX table name)
          const { error: updateError } = await supabase.from('delivery_persons').update({ status }).eq('id', id);
          if (updateError) throw updateError;

          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if (profile) {
               let roles = profile.roles || [];
               let changed = false;
               if (status === 'approved') {
                   if (!roles.includes('deliveryPerson')) { roles.push('deliveryPerson'); changed = true; }
               } else {
                   // Optional: Remove role if suspended? 
                   // For now, keep role so they can see dashboard "suspended" status
               }
               if (changed) await supabase.from('profiles').update({ roles }).eq('id', uid);
          }
          showToast(`Rider ${status}`, "success");
          await fetchData(); 
      } catch (e: any) { showToast(`Failed: ${e.message}`, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, connectionError, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson> & { phoneNumber?: string }) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  // New Logistics
  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

// Coordinate Resolver Helper
const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    // Default fallback to Legon Campus center if completely unknown
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              // Enhanced Notification
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

                  // Vendor Alert
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              // Driver Alert
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as Order;
                  if (currentRoleRef.current === 'deliveryPerson' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.deliveryPersonId) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
              showToast("Connection failed. Please check your internet or API keys.", "error");
          }
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id, data.session.user);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
          if (e.message !== "Vendor account pending approval" && e.message !== "Account Suspended") {
             // throw e; // don't rethrow to keep app alive
          }
      } 
  };

  const fetchUserProfile = async (userId: string, sessionUser?: any) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          // PGRST116 Fix: Use maybeSingle() instead of single()
          // This prevents crashing if the profile row is missing (e.g., registration race condition)
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();

          if (error) throw error;

          if (data) {
              if (data.isBanned) {
                  throw new Error("Account Suspended");
              }

              if (data.roles?.includes('vendor') && !data.roles.includes('admin')) {
                  const { data: v } = await supabase.from('vendors').select('is_approved').eq('user_id', userId).maybeSingle();
                  if (v && v.is_approved === false) {
                       throw new Error("Vendor account pending approval");
                  }
              }

              const user: User = { ...data, roles: data.roles || ['buyer'] };
              setCurrentUser(user);

              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          } else {
              // Profile row is missing.
              // AUTO-RECOVERY: If we have session details, recreate the profile row.
              if (sessionUser) {
                  console.warn(`Profile missing for user ${userId}. Attempting auto-recovery...`);
                  const { error: insertError } = await supabase.from('profiles').insert({
                      id: userId,
                      email: sessionUser.email,
                      name: sessionUser.user_metadata?.full_name || sessionUser.email?.split('@')[0] || 'Restored User',
                      roles: ['buyer']
                  });

                  if (!insertError) {
                      showToast("Profile restored automatically", "success");
                      // Retry fetch with the new data (pass undefined for sessionUser to avoid infinite loop risk, though rare)
                      return fetchUserProfile(userId, undefined);
                  } else {
                      console.error("Auto-recovery failed:", insertError);
                  }
              }

              console.warn(`Profile missing for user ${userId}. Cleaning up session.`);
              await supabase.auth.signOut();
              setCurrentUser(null);
              return null;
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
          if (e.message === "Account Suspended" || e.message === "Vendor account pending approval") {
               await supabase.auth.signOut();
               setCurrentUser(null);
               throw e; 
          }
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e: any) { 
                 // Log detail error message instead of [object Object]
                 console.error(`Fetch ${table} failed:`, e.message || e);
                 return null;
             }
          };

          // Fetch tables individually.
          const [pData, vData, oData] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at')
          ]);

          // Fallback logic for delivery persons (handle both table names)
          let dDataRaw = await fetchSafely('delivery_persons');
          if (!dDataRaw) {
              console.warn("delivery_persons table fetch failed, trying 'couriers' table...");
              dDataRaw = await fetchSafely('couriers');
          }

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
                  locationCoordinates: o.locationCoordinates || o.location_coordinates,
                  pickupCoordinates: o.pickupCoordinates || o.pickup_coordinates,
              })) as Order[]);
          }

          // Manual Join for Profiles
          let dData = dDataRaw;
          if (dDataRaw && dDataRaw.length > 0) {
              try {
                  const userIds = [...new Set(dDataRaw.map((d: any) => d.user_id).filter(Boolean))];
                  if (userIds.length > 0) {
                      const { data: profiles } = await supabase
                          .from('profiles')
                          .select('id, name, email')
                          .in('id', userIds);

                      if (profiles) {
                          const profileMap = new Map(profiles.map((p: any) => [p.id, p]));
                          dData = dDataRaw.map((d: any) => ({
                              ...d,
                              profiles: profileMap.get(d.user_id) || {}
                          }));
                      }
                  }
              } catch (err) {
                  console.error("Manual profile join failed for delivery persons", err);
              }
          }

          if (dData) setDeliveryPersons(dData.map((d: any) => {
             const profile = d.profiles || {}; 
             // Use d.full_name from table if available, fallback to profile name
             const name = profile.name || d.full_name || 'Courier';

             // Map 'verified' (legacy) to status if status is missing
             let status = d.status || 'pending';
             if (!d.status && d.verified === true) status = 'approved';

             return {
                 ...d,
                 id: d.id,
                 userId: d.user_id,
                 fullName: name, // From profiles or direct
                 vehicleType: d.vehicle_type || 'Motorbike', 

                 // Handle potentially missing columns gracefully
                 onlineStatus: d.online_status ?? false, 
                 currentLat: d.current_lat,
                 currentLng: d.current_lng,
                 availabilityStatus: d.availability_status,
                 verified: status === 'approved',

                 status: status,
                 rating: d.delivery_rating || d.rating || 5.0
             };
          }) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }

          setConnectionError(false); 
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
          if (e.message?.includes("fetch") || e.message?.includes("Network")) {
              setConnectionError(true);
          }
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
           return { success: false, error: error.message === "Invalid login credentials" ? "Invalid email or password" : error.message };
      }

      if (data.user) {
          try {
            const user = await fetchUserProfile(data.user.id, data.user);
            if (!user) return { success: false, error: "Account profile missing. Please contact support." };

            fetchData();

            let role: Role = 'buyer';
            if (user) {
                const persistedRole = localStorage.getItem('lynqed_role') as Role;
                if (persistedRole && user.roles.includes(persistedRole)) {
                    role = persistedRole;
                } else {
                     if (user.roles.includes('admin')) role = 'admin';
                     else if (user.roles.includes('vendor')) role = 'vendor';
                     else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
                }
            }
            return { success: true, role }; 
          } catch (e: any) {
              return { success: false, error: e.message || "Login failed" };
          }
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           // Insert profile with phone number
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               phone_number: phoneNumber 
           });

           // Automatically log in after signup
           await login(email, password); 
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // 0. Update Profile Phone if provided
          if (data.phoneNumber) {
              await supabase.from('profiles').update({ phone_number: data.phoneNumber }).eq('id', currentUser.id);
          }

          // Check if already registered (Checking both tables for safety)
          const { data: existingDP } = await supabase.from('delivery_persons').select('id').eq('user_id', currentUser.id).maybeSingle();
          const { data: existingCourier } = await supabase.from('couriers').select('id').eq('user_id', currentUser.id).maybeSingle();

          if (existingDP || existingCourier) {
              showToast("You are already registered as a courier.", "info");
              return { success: true };
          }

          // 2. Insert into 'delivery_persons' (Standard)
          // Fallback to 'couriers' if 'delivery_persons' fails
          let error;
          try {
             const { error: dpError } = await supabase.from('delivery_persons').insert({ 
                  user_id: currentUser.id, 
                  status: 'pending', 
                  full_name: data.fullName || currentUser.name,
                  vehicle_type: data.vehicleType || 'bicycle'
              });
              error = dpError;
          } catch(e) { error = e; }

          if (error) {
              console.warn("delivery_persons insert failed, trying couriers", error);
              // Fallback for legacy schema
              const { error: cError } = await supabase.from('couriers').insert({ 
                  user_id: currentUser.id, 
                  verified: false,
                  status: 'pending',
                  full_name: data.fullName || currentUser.name,
                  vehicle_type: data.vehicleType || 'bicycle'
              });
              if(cError) throw cError;
          }

          // 3. CRITICAL: Add role to profile immediately so they can access dashboard (where they see "Pending")
          if (!currentUser.roles.includes('deliveryPerson')) {
              const newRoles: Role[] = [...currentUser.roles, 'deliveryPerson'];
              await supabase.from('profiles').update({ roles: newRoles }).eq('id', currentUser.id);
              // Update local state
              setCurrentUser({ ...currentUser, roles: newRoles });
          }

          showToast("Rider application submitted", "success"); 
          await fetchData();
          return { success: true };
      } catch (err: any) {
          console.error("Exception during registration:", err);
          showToast(`Application failed: ${err.message || 'Unknown error'}`, "error");
          return { success: false };
      }
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found.", "error"); return false; }
      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const { error } = await supabase.from('products').update({ ...rest, contact_phone: contactPhone }).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);

              // Geo Logic: Resolve Coordinates for Map Routing
              // 1. Vendor Location
              const vendorCoords = vendor ? resolveCoordinates(vendor.location) : undefined;
              // 2. Buyer Location (Ideally from profile or input, defaulting to current GPS if user permitted it, or default cache)
              // For MVP, if we don't have user address input, we assume a central campus location or null
              const buyerCoords = currentUser.defaultLocation ? resolveCoordinates(currentUser.defaultLocation) : { lat: 5.6506, lng: -0.1962 };

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option,
                  // Save geospatial data for routing
                  pickup_coordinates: vendorCoords,
                  location_coordinates: buyerCoords
              });

              if (error) throw error;
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;

      try {
          // Concurrency Check: Ensure it wasn't just taken
          const { data: check } = await supabase.from('orders').select('delivery_person_id').eq('id', oid).single();
          if (check && check.delivery_person_id) {
              showToast("Job was just taken by another driver.", "error");
              await fetchData();
              return;
          }

          const { error } = await supabase
              .from('orders')
              .update({
                  delivery_person_id: currentUser.id,
                  status: 'courier_assigned'
              })
              .eq('id', oid);

          if (error) throw error;

          showToast("Job Accepted! Head to vendor.", "success");
          await fetchData();
      } catch (e: any) {
          console.error("Assign Error:", e);
          showToast("Failed to accept job.", "error");
      }
  };

  // Logistics
  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      // Find delivery profile ID
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      try {
          // Update 'delivery_persons' table (FIX: using correct table name)
          // Also try fallback to couriers if needed
          const { error } = await supabase.from('delivery_persons').update({ online_status: isOnline }).eq('id', dProfile.id);

          if (error) {
              console.warn("Could not update status in delivery_persons, trying couriers", error);
              await supabase.from('couriers').update({ online_status: isOnline }).eq('id', dProfile.id);
          }
          await fetchData();
          showToast(isOnline ? "You are now ONLINE" : "You are now OFFLINE", "info");
      } catch(e) { console.error(e); }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser || currentRole !== 'deliveryPerson') return;
      const dProfile = deliveryPersons.find(d => d.userId === currentUser.id);
      if(!dProfile) return;

      // 1. Database Update (Update 'delivery_persons')
      // Note: This might fail if user hasn't added current_lat/lng columns, but we try anyway.
      supabase.from('delivery_persons').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id)
        .then(({ error }) => {
            if (error) {
                 // Fallback
                 supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', dProfile.id).then();
            }
        });

      // 2. Realtime Broadcast (Cheaper, faster for live tracking maps)
      const channel = supabase.channel(`courier_tracking:${dProfile.id}`);
      channel.subscribe((status) => {
          if (status === 'SUBSCRIBED') {
              channel.send({
                  type: 'broadcast',
                  event: 'location',
                  payload: { lat, lng, courierId: dProfile.id }
              });
          }
      });
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);
      if (!vendor) return;
      try {
          let query = vendor.id 
             ? supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id)
             : supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          const { error } = await query;
          if (error) throw error;
          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: 'approved' | 'rejected' | 'suspended') => { 
      try {
          // Update 'delivery_persons' table (FIX table name)
          const { error: updateError } = await supabase.from('delivery_persons').update({ status }).eq('id', id);

          if (updateError) {
             // Fallback to legacy
             await supabase.from('couriers').update({ status }).eq('id', id);
          }

          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if (profile) {
               let roles = profile.roles || [];
               let changed = false;
               if (status === 'approved') {
                   if (!roles.includes('deliveryPerson')) { roles.push('deliveryPerson'); changed = true; }
               } else {
                   // Optional: Remove role if suspended? 
                   // For now, keep role so they can see dashboard "suspended" status
               }
               if (changed) await supabase.from('profiles').update({ roles }).eq('id', uid);
          }
          showToast(`Rider ${status}`, "success");
          await fetchData(); 
      } catch (e: any) { showToast(`Failed: ${e.message}`, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, connectionError, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};
